<?php
namespace App\Domain\AI\Channels\Webchat\Services;
use App\Domain\AI\Agents\Models\Agent;use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Channels\Webchat\Models\WebchatChannel;use App\Domain\AI\Channels\Webchat\Support\WebchatOriginPolicy;use App\Domain\AI\Tenancy\AiTenantBoundary;use App\Domain\AI\Usage\AiCapacityService;use App\Domain\Network\Tenancy\Models\Tenant;use App\Models\User;use Illuminate\Support\Facades\DB;
final class ManageWebchatChannelService{
 public function __construct(private AiLifecycleAuthorization$auth,private AiTenantBoundary$tenants,private WebchatOriginPolicy$origins,private AiCapacityService$capacity){}
 public function save(User$actor,Agent$input,array$data):WebchatChannel{$x=$this->auth->authorize($actor);$this->tenants->assertResourceBelongsToCurrentTenant($input);return DB::transaction(function()use($x,$input,$data){$this->auth->revalidate($x);$tenant=Tenant::findOrFail($x->tenantId);$this->capacity->lockAuthority($tenant);$agent=Agent::lockForUpdate()->findOrFail($input->id);$origins=array_values(array_unique(array_map(fn($v)=>$this->origins->canonicalize((string)$v,app()->environment(['local','testing'])),$data['allowed_origins'])));if(count($origins)>(int)config('ai.webchat.max_allowed_origins',20))throw new \DomainException('Too many allowed origins.');$channel=WebchatChannel::where('tenant_id',$x->tenantId)->where('agent_id',$agent->id)->lockForUpdate()->first()??new WebchatChannel;if(!$channel->exists&&$this->capacity->capacity($tenant,AiCapacityService::MAX_WEBCHAT_CHANNELS)->reached())throw new \App\Domain\AI\Usage\Exceptions\AiCapacityExceededException(AiCapacityService::MAX_WEBCHAT_CHANNELS);$channel->tenant_id=$x->tenantId;$channel->agent_id=$agent->id;$channel->created_by_user_id??=$x->actorUserId;$channel->display_name=$data['display_name'];$channel->welcome_message=$data['welcome_message']??null;$channel->primary_color=strtoupper($data['primary_color']);$channel->launcher_label=$data['launcher_label'];$channel->allowed_origins=$origins;$channel->enabled=(bool)$data['enabled'];if($channel->enabled&&$agent->current_published_version_id===null)throw new \DomainException('Publish an Agent Version before enabling Webchat.');$channel->save();return$channel->fresh();});}
 public function rotate(User$actor,Agent$input):WebchatChannel{$x=$this->auth->authorize($actor);$this->tenants->assertResourceBelongsToCurrentTenant($input);return DB::transaction(function()use($x,$input){$tenant=Tenant::findOrFail($x->tenantId);$this->capacity->lockAuthority($tenant);Agent::lockForUpdate()->findOrFail($input->id);$c=WebchatChannel::where('tenant_id',$x->tenantId)->where('agent_id',$input->id)->lockForUpdate()->firstOrFail();DB::table('ai_webchat_channel_keys')->insert(['tenant_id'=>$c->tenant_id,'webchat_channel_id'=>$c->id,'public_key'=>$c->public_key,'created_at'=>now(),'updated_at'=>now()]);$c->public_key='wc_'.rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$c->save();return$c->fresh();});}
}
